function normalizePlaceName(value){return String(value||'').trim().replace(/[\s·•,，/／-]/g,'');}
const CITY_INDEX=new Map();
const CITY_OPTIONS=[];
function addCityAlias(alias,coordinates,canonical){const key=normalizePlaceName(alias);if(!key)return;const old=CITY_INDEX.get(key);if(old&&old.canonical!==canonical){CITY_INDEX.set(key,{ambiguous:true});return;}if(old?.ambiguous)return;CITY_INDEX.set(key,{coordinates,canonical});}
for(const [province,full,short,lon,lat] of CHINA_PLACES){
 const coordinates=[lon,lat,8],canonical=province+' '+full;
 const provinceShort=province.replace(/壮族自治区|回族自治区|维吾尔自治区|自治区|省|市$/g,'');
 const shortBase=short.replace(/市$|地区$|盟$|州$/g,'');
 const aliases=new Set([full,short,shortBase]);
 // “海南” on its own usually denotes the province, not Qinghai's prefecture.
 if(full==='海南藏族自治州'){aliases.delete('海南');aliases.add('海南州');}
 for(const alias of aliases){addCityAlias(alias,coordinates,canonical);addCityAlias(province+alias,coordinates,canonical);addCityAlias(provinceShort+alias,coordinates,canonical);}
 // A concise autonomous-prefecture name with “州” is a useful everyday spelling.
 if(full.endsWith('自治州')){addCityAlias(shortBase+'州',coordinates,canonical);addCityAlias(provinceShort+shortBase+'州',coordinates,canonical);}
 CITY_OPTIONS.push(canonical);
}
for(const [name,coordinates] of Object.entries(CITIES)){if(!CITY_INDEX.has(name)){addCityAlias(name,coordinates,name);addCityAlias(name+'市',coordinates,name);CITY_OPTIONS.push(name);}}
const ZODIAC_NAMES=['白羊座','金牛座','双子座','巨蟹座','狮子座','处女座','天秤座','天蝎座','射手座','摩羯座','水瓶座','双鱼座'];
function cityLookup(value){const match=CITY_INDEX.get(normalizePlaceName(value));return match&&!match.ambiguous?match.coordinates:null;}
function birthInstant(p){return Date.parse(`${p.date}T${p.time}:00Z`)-Number(p.zone??8)*3600000;}
function ascendant(p){const city=cityLookup(p.place);if(!city)return null;const jd=birthInstant(p)/86400000+2440587.5,T=(jd-2451545)/36525;const theta=mod(280.46061837+360.98564736629*(jd-2451545)+.000387933*T*T-T*T*T/38710000+city[0],360)*Math.PI/180;const eps=(23.43929111-.013004167*T)*Math.PI/180,phi=city[1]*Math.PI/180;const longitude=mod(Math.atan2(-Math.cos(theta),Math.sin(theta)*Math.cos(eps)+Math.tan(phi)*Math.sin(eps))*180/Math.PI+180,360);const index=Math.floor(longitude/30);return {sign:ZODIAC_NAMES[index],longitude,degree:Math.floor(longitude%30*10)/10,boundary:Math.min(longitude%30,30-longitude%30)<2};}
function sunSign(p){return ZODIAC_NAMES[Math.floor(solarLongitude(birthInstant(p))/30)];}
